problems.solutionCode:
type ImportOutcome =
  | { state: 'accepted'; acceptedRows: number }
  | { state: 'rejected'; reason: string };

function assertNever(value: never): never {
  throw new Error(`Unhandled import outcome: ${JSON.stringify(value)}`);
}

export function summarizeImportOutcome(outcome: ImportOutcome): string {
  switch (outcome.state) {
    case 'accepted':
      return `Accepted ${outcome.acceptedRows} rows`;
    case 'rejected':
      return `Rejected: ${outcome.reason}`;
    default:
      return assertNever(outcome);
  }
}

