  throw new Error(`Unhandled permit state: ${JSON.stringify(value)}`);
}

export function nextPermitStep(state: PermitState): string {
  switch (state.status) {
    case 'draft':
      return 'Complete the application';
    case 'submitted':
      return `Wait for review of ${state.applicationId}`;
    case 'approved':
      return `Issue permit ${state.permitId}`;
    case 'rejected':
      return `Revise application: ${state.reason}`;
    default:
      return assertNever(state);
  }
}

